import{_ as p,a0 as t,w as o,s as d,ao as r,I as l,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"讓你提高效率的 Linux 技巧 | LCTT x X-CMD","titleTemplate":false,"description":"讓你提高效率的 Linux 技巧 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"讓你提高效率的 Linux 技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"讓你提高效率的 Linux 技巧 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180917 Linux tricks that can save you time and trouble","title":"讓你提高效率的 Linux 技巧","tag":"201809","desc":""},"relativePath":"201809/20180917 Linux tricks that can save you time and trouble.md","filePath":"[post].md"}'),c={name:"201809/20180917 Linux tricks that can save you time and trouble.md"};function h(u,s,g,k,b,f){const n=t("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="讓你提高效率的-linux-技巧" tabindex="-1">讓你提高效率的 Linux 技巧 <a class="header-anchor" href="#讓你提高效率的-linux-技巧" aria-label="Permalink to “讓你提高效率的 Linux 技巧”">​</a></h1><blockquote><p>想要在 Linux 命令列工作中提高效率，你需要使用一些技巧。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2018/09/boy-jumping-off-swing-100772498-large.jpg" alt=""></p><p>巧妙的 Linux 命令列技巧能讓你節省時間、避免出錯，還能讓你記住和複用各種複雜的命令，專注在需要做的事情本身，而不是你要怎麼做。以下介紹一些好用的命令列技巧。</p><h3 id="命令編輯" tabindex="-1">命令編輯 <a class="header-anchor" href="#命令編輯" aria-label="Permalink to “命令編輯”">​</a></h3><p>如果要對一個已輸入的命令進行修改，可以使用 <code>^a</code>（<code>ctrl + a</code>）或 <code>^e</code>（<code>ctrl + e</code>）將光標快速移動到命令的開頭或命令的末尾。</p><p>還可以使用 <code>^</code> 字符實現對上一個命令的文本替換並重新執行命令，例如 <code>^before^after^</code> 相當於把上一個命令中的 <code>before</code> 替換為 <code>after</code> 然後重新執行一次。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ eho hello world  &lt;== 錯誤的命令</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Command &#39;eho&#39; not found, did you mean:</span></span>
<span class="line"><span></span></span>
<span class="line"><span> command &#39;echo&#39; from deb coreutils</span></span>
<span class="line"><span> command &#39;who&#39; from deb coreutils</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Try: sudo apt install &lt;deb name&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ^e^ec^        &lt;== 替換</span></span>
<span class="line"><span>echo hello world</span></span>
<span class="line"><span>hello world</span></span></code></pre></div><h3 id="使用遠程機器的名稱登錄到機器上" tabindex="-1">使用遠程機器的名稱登錄到機器上 <a class="header-anchor" href="#使用遠程機器的名稱登錄到機器上" aria-label="Permalink to “使用遠程機器的名稱登錄到機器上”">​</a></h3><p>如果使用命令列登錄其它機器上，可以考慮添加別名。在別名中，可以填入需要登錄的用户名（與本地系統上的用户名可能相同，也可能不同）以及遠程機器的登錄信息。例如使用 <code>server_name =&#39;ssh -v -l username IP-address&#39;</code> 這樣的別名命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias butterfly=”ssh -v -l jdoe 192.168.0.11”</span></span></code></pre></div><p>也可以通過在 <code>/etc/hosts</code> 文件中添加記錄或者在 DNS 服務器中加入解析記錄來把 IP 地址替換成易記的機器名稱。</p><p>執行 <code>alias</code> 命令可以列出機器上已有的別名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias</span></span>
<span class="line"><span>alias butterfly=&#39;ssh -v -l jdoe 192.168.0.11&#39;</span></span>
<span class="line"><span>alias c=&#39;clear&#39;</span></span>
<span class="line"><span>alias egrep=&#39;egrep --color=auto&#39;</span></span>
<span class="line"><span>alias fgrep=&#39;fgrep --color=auto&#39;</span></span>
<span class="line"><span>alias grep=&#39;grep --color=auto&#39;</span></span>
<span class="line"><span>alias l=&#39;ls -CF&#39;</span></span>
<span class="line"><span>alias la=&#39;ls -A&#39;</span></span>
<span class="line"><span>alias list_repos=&#39;grep ^[^#] /etc/apt/sources.list /etc/apt/sources.list.d/*&#39;</span></span>
<span class="line"><span>alias ll=&#39;ls -alF&#39;</span></span>
<span class="line"><span>alias ls=&#39;ls --color=auto&#39;</span></span>
<span class="line"><span>alias show_dimensions=&#39;xdpyinfo | grep &#39;\\&#39;&#39;dimensions:&#39;\\&#39;&#39;&#39;</span></span></code></pre></div><p>只要將新的別名添加到 <code>~/.bashrc</code> 或類似的文件中，就可以讓別名在每次登錄後都能立即生效。</p><h3 id="凍結、解凍終端界面" tabindex="-1">凍結、解凍終端界面 <a class="header-anchor" href="#凍結、解凍終端界面" aria-label="Permalink to “凍結、解凍終端界面”">​</a></h3><p><code>^s</code>（<code>ctrl + s</code>）將通過執行流量控制命令 XOFF 來停止終端輸出內容，這會對 PuTTY 會話和桌面終端窗口產生影響。如果誤輸入了這個命令，可以使用 <code>^q</code>（<code>ctrl + q</code>）讓終端重新響應。所以只需要記住 <code>^q</code> 這個組合鍵就可以了，畢竟這種情況並不多見。</p><h3 id="複用命令" tabindex="-1">複用命令 <a class="header-anchor" href="#複用命令" aria-label="Permalink to “複用命令”">​</a></h3><p>Linux 提供了很多讓用户複用命令的方法，其核心是通過歷史緩衝區收集執行過的命令。複用命令的最簡單方法是輸入 <code>!</code> 然後接最近使用過的命令的開頭字母；當然也可以按鍵盤上的向上箭頭，直到看到要複用的命令，然後按回車鍵。還可以先使用 <code>history</code> 顯示命令歷史，然後輸入 <code>!</code> 後面再接命令歷史記錄中需要複用的命令旁邊的數字。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>!! &lt;== 複用上一條命令</span></span>
<span class="line"><span>!ec &lt;== 複用上一條以 “ec” 開頭的命令</span></span>
<span class="line"><span>!76 &lt;== 複用命令歷史中的 76 號命令</span></span></code></pre></div><h3 id="查看日誌文件並動態顯示更新內容" tabindex="-1">查看日誌文件並動態顯示更新內容 <a class="header-anchor" href="#查看日誌文件並動態顯示更新內容" aria-label="Permalink to “查看日誌文件並動態顯示更新內容”">​</a></h3><p>使用形如 <code>tail -f /var/log/syslog</code> 的命令可以查看指定的日誌文件，並動態顯示文件中增加的內容，需要監控向日志文件中追加內容的的事件時相當有用。這個命令會輸出文件內容的末尾部分，並逐漸顯示新增的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tail -f /var/log/auth.log</span></span>
<span class="line"><span>Sep 17 09:41:01 fly CRON[8071]: pam_unix(cron:session): session closed for user smmsp</span></span>
<span class="line"><span>Sep 17 09:45:01 fly CRON[8115]: pam_unix(cron:session): session opened for user root</span></span>
<span class="line"><span>Sep 17 09:45:01 fly CRON[8115]: pam_unix(cron:session): session closed for user root</span></span>
<span class="line"><span>Sep 17 09:47:00 fly sshd[8124]: Accepted password for shs from 192.168.0.22 port 47792</span></span>
<span class="line"><span>Sep 17 09:47:00 fly sshd[8124]: pam_unix(sshd:session): session opened for user shs by</span></span>
<span class="line"><span>Sep 17 09:47:00 fly systemd-logind[776]: New session 215 of user shs.</span></span>
<span class="line"><span>Sep 17 09:55:01 fly CRON[8208]: pam_unix(cron:session): session opened for user root</span></span>
<span class="line"><span>Sep 17 09:55:01 fly CRON[8208]: pam_unix(cron:session): session closed for user root</span></span>
<span class="line"><span>        &lt;== 等待顯示追加的內容</span></span></code></pre></div><h3 id="尋求幫助" tabindex="-1">尋求幫助 <a class="header-anchor" href="#尋求幫助" aria-label="Permalink to “尋求幫助”">​</a></h3><p>對於大多數 Linux 命令，都可以通過在輸入命令後加上選項 <code>--help</code> 來獲得這個命令的作用、用法以及它的一些相關信息。除了 <code>man</code> 命令之外， <code>--help</code> 選項可以讓你在不使用所有擴展選項的情況下獲取到所需要的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir --help</span></span>
<span class="line"><span>Usage: mkdir [OPTION]... DIRECTORY...</span></span>
<span class="line"><span>Create the DIRECTORY(ies), if they do not already exist.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Mandatory arguments to long options are mandatory for short options too.</span></span>
<span class="line"><span> -m, --mode=MODE set file mode (as in chmod), not a=rwx - umask</span></span>
<span class="line"><span> -p, --parents no error if existing, make parent directories as needed</span></span>
<span class="line"><span> -v, --verbose print a message for each created directory</span></span>
<span class="line"><span> -Z set SELinux security context of each created directory</span></span>
<span class="line"><span> to the default type</span></span>
<span class="line"><span> --context[=CTX] like -Z, or if CTX is specified then set the SELinux</span></span>
<span class="line"><span> or SMACK security context to CTX</span></span>
<span class="line"><span> --help display this help and exit</span></span>
<span class="line"><span> --version output version information and exit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GNU coreutils online help: &lt;http://www.gnu.org/software/coreutils/&gt;</span></span>
<span class="line"><span>Full documentation at: &lt;http://www.gnu.org/software/coreutils/mkdir&gt;</span></span>
<span class="line"><span>or available locally via: info &#39;(coreutils) mkdir invocation&#39;</span></span></code></pre></div><h3 id="謹慎刪除文件" tabindex="-1">謹慎刪除文件 <a class="header-anchor" href="#謹慎刪除文件" aria-label="Permalink to “謹慎刪除文件”">​</a></h3><p>如果要謹慎使用 <code>rm</code> 命令，可以為它設置一個別名，在刪除文件之前需要進行確認才能刪除。有些系統管理員會默認使用這個別名，對於這種情況，你可能需要看看下一個技巧。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rm -i    &lt;== 請求確認</span></span></code></pre></div><h3 id="關閉別名" tabindex="-1">關閉別名 <a class="header-anchor" href="#關閉別名" aria-label="Permalink to “關閉別名”">​</a></h3><p>你可以使用 <code>unalias</code> 命令以交互方式禁用別名。它不會更改別名的配置，而僅僅是暫時禁用，直到下次登錄或重新設置了這一個別名才會重新生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unalias rm</span></span></code></pre></div><p>如果已經將 <code>rm -i</code> 默認設置為 <code>rm</code> 的別名，但你希望在刪除文件之前不必進行確認，則可以將 <code>unalias</code> 命令放在一個啓動文件（例如 <code>~/.bashrc</code>）中。</p><h3 id="使用-sudo" tabindex="-1">使用 sudo <a class="header-anchor" href="#使用-sudo" aria-label="Permalink to “使用 sudo”">​</a></h3><p>如果你經常在只有 root 用户才能執行的命令前忘記使用 <code>sudo</code>，這裏有兩個方法可以解決。一是利用命令歷史記錄，可以使用 <code>sudo !!</code>（使用 <code>!!</code> 來運行最近的命令，並在前面添加 <code>sudo</code>）來重複執行，二是設置一些附加了所需 <code>sudo</code> 的命令別名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias update=’sudo apt update’</span></span></code></pre></div><h3 id="更復雜的技巧" tabindex="-1">更復雜的技巧 <a class="header-anchor" href="#更復雜的技巧" aria-label="Permalink to “更復雜的技巧”">​</a></h3><p>有時命令列技巧並不僅僅是一個別名。畢竟，別名能幫你做的只有替換命令以及增加一些命令參數，節省了輸入的時間。但如果需要比別名更復雜功能，可以通過編寫腳本、向 <code>.bashrc</code> 或其他啓動文件添加函數來實現。例如，下面這個函數會在創建一個目錄後進入到這個目錄下。在設置完畢後，執行 <code>source .bashrc</code>，就可以使用 <code>md temp</code> 這樣的命令來創建目錄立即進入這個目錄下。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>md () { mkdir -p &quot;$@&quot; &amp;&amp; cd &quot;$1&quot;; }</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>使用 Linux 命令列是在 Linux 系統上工作最有效也最有趣的方法，但配合命令列技巧和巧妙的別名可以讓你獲得更好的體驗。</p><hr>`,42)),l("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3305811/linux/linux-tricks-that-even-you-can-love.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3305811/linux/linux-tricks-that-even-you-can-love.html",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/HankChow"},{default:i(()=>[...s[4]||(s[4]=[a("HankChow",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=p(c,[["render",h]]);export{y as __pageData,C as default};
